```cpp
bool MapGrid::IsValidPixel(int col, int row) const {
  return col >= 0 && row >= 0 &&
         static_cast<uint32_t>(col) < width &&
         static_cast<uint32_t>(row) < height;
}

int8_t MapGrid::GetValue(int col, int row) const {
  if (!IsValidPixel(col, row)) return kUnknown; // -1
  const size_t index = static_cast<size_t>(row) * width + static_cast<size_t>(col);
  if (index >= data.size()) return kUnknown;
  return data[index];
